import java.util.*;
import java.io.*;

public class Main {
    static final long mod1 = 998244353L;
    static final long mod2 = 1000000007L;
    static final long[] pw = {1L, 10L, 100L, 1000L, 10000L, 100000L, 1000000L};
    static long[] s = new long[7];
    static long answer = 0;
    static long count1 = 0;
    static long total;
    static long count2 = 0;
    static List<Long>[] v = new ArrayList[7];

    public static void generate_sequences(int level, long value) {
        if (level == 7) return;
        v[level].add((count1 - value + mod1) % mod1);
        s[level] += (count1 - value + mod1) % mod1;
        count1++;
        for (int digit = 0; digit <= 9; digit++) {
            generate_sequences(level + 1, value * 10 + digit);
        }
    }

    public static boolean is_valid(long x) {
        return x * pw[6] + 999999 <= total && x * pw[6] * 10 > total;
    }

    public static void explore(int level, long current) {
        if (current > total) return;
        if (is_valid(current)) {
            for (int i = 0; i <= 6; i++) {
                long p = ((count2 + 1 - (current * pw[i]) % mod1) + mod1) % mod1;
                int w = lowerBound(v[i], mod1 - p);
                long size = v[i].size();
                answer = (answer + (s[i] + p * size - mod1 * (size - w))) % mod2;
            }
            count2 += count1;
            return;
        }
        count2++;
        answer = (answer + ((count2 - current) % mod1 + mod1) % mod1) % mod2;
        int startDigit = (level == 0) ? 1 : 0;
        for (int i = startDigit; i <= 9; i++) {
            explore(level + 1, current * 10 + i);
        }
    }

    public static int lowerBound(List<Long> list, long key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= key) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        total = Long.parseLong(br.readLine());
        for (int i = 0; i < 7; i++) {
            v[i] = new ArrayList<>();
        }
        generate_sequences(0, 0);
        for (int i = 0; i <= 6; i++) {
            Collections.sort(v[i]);
        }
        count2 = -1;
        explore(0, 0);
        System.out.println(answer);
    }
}
